declare(strict_types=1);require_once __DIR__.'/PaymentReportingScope.php';require_once __DIR__.'/AccountingReportingPeriod.php';final class AccountingReportingService{public function __construct(private PDO $pdo){}private function rows($q,$p=[]){$s=$this->pdo->prepare($q);$s->execute($p);return $s->fetchAll(PDO::FETCH_ASSOC);}private function num($q,$p=[]):float{$s=$this->pdo->prepare($q);$s->execute($p);return(float)($s->fetchColumn()?:0);}public function filters(array $i):array{$ay=trim((string)($i['academic_year']??''));$sem=(string)($i['semester']??'');if($ay===''||!in_array($sem,['1st','2nd','Summer'],true)){$t=$this->rows('SELECT academic_year,semester FROM billing ORDER BY academic_year DESC,billing_id DESC LIMIT 1');$ay=$ay?:($t[0]['academic_year']??'');$sem=in_array($sem,['1st','2nd','Summer'],true)?$sem:($t[0]['semester']??'1st');}if($ay==='')throw new InvalidArgumentException('No academic billing cohort is available.');$r=AccountingReportingPeriod::fromRequest($i);$channel=trim((string)($i['payment_channel']??''));$category=filter_var($i['fee_category']??null,FILTER_VALIDATE_INT);return ['academic_year'=>$ay,'semester'=>$sem,'range'=>$r,'payment_channel'=>$channel?:null,'fee_category'=>$category&&$category>0?$category:null];}private function base($f,&$p){$p=[$f['academic_year'],$f['semester']];$join=' FROM payment_allocations pa JOIN payments p ON p.payment_id=pa.payment_id JOIN billing_items bi ON bi.billing_item_id=pa.billing_item_id JOIN billing b ON b.billing_id=bi.billing_id JOIN fees f ON f.fee_id=bi.fee_id ';$where=' WHERE '.PaymentReportingScope::officialCondition('p').' AND b.academic_year=? AND b.semester=?';if($f['payment_channel']){$where.=' AND p.payment_channel=?';$p[]=$f['payment_channel'];}if($f['fee_category']){$where.=' AND f.category_id=?';$p[]=$f['fee_category'];}return[$join,$where];}private function collections($f,$start,$end):float{$p=[];[$j,$w]=$this->base($f,$p);$p[]=AccountingReportingPeriod::sql($start);$p[]=AccountingReportingPeriod::sql($end);return $this->num('SELECT COALESCE(SUM(pa.allocated_amount),0)'.$j.$w.' AND p.verified_at>=? AND p.verified_at<?',$p);}public function report(array $i):array{$f=$this->filters($i);$r=$f['range'];$net=$this->num('SELECT COALESCE(SUM(total_amount-COALESCE(discount_amount,0)),0) FROM billing WHERE academic_year=? AND semester=?',[$f['academic_year'],$f['semester']]);$out=$this->num("SELECT COALESCE(SUM(remaining_balance),0) FROM billing WHERE academic_year=? AND semester=? AND billing_status IN ('Unpaid','Partial')",[$f['academic_year'],$f['semester']]);$current=$this->collections($f,$r['start_at'],$r['end_exclusive']);$cutoff=$this->termCutoff($f,$r['end_exclusive']);$eff=$net>0?$cutoff/$net*100:null;$p=[];[$j,$w]=$this->base($f,$p);$p[]=AccountingReportingPeriod::sql($r['start_at']);$p[]=AccountingReportingPeriod::sql($r['end_exclusive']);$categories=$this->rows('SELECT fc.category_name label,SUM(pa.allocated_amount) total'.$j.' JOIN fee_categories fc ON fc.category_id=f.category_id '.$w.' AND p.verified_at>=? AND p.verified_at<? GROUP BY fc.category_id,fc.category_name ORDER BY total DESC',$p);$p=[];[$j,$w]=$this->base($f,$p);$p[]=AccountingReportingPeriod::sql($r['start_at']);$p[]=AccountingReportingPeriod::sql($r['end_exclusive']);$channels=$this->rows('SELECT p.payment_channel label,SUM(pa.allocated_amount) total'.$j.$w.' AND p.verified_at>=? AND p.verified_at<? GROUP BY p.payment_channel ORDER BY total DESC',$p);$p=[];[$j,$w]=$this->base($f,$p);$p[]=AccountingReportingPeriod::sql($r['start_at']);$p[]=AccountingReportingPeriod::sql($r['end_exclusive']);$recent=$this->rows('SELECT p.payment_id,p.verified_at,p.receipt_number,p.reference_number,p.transaction_type,p.payment_channel,MAX(s.student_number) student_number,MAX(s.full_name) full_name,SUM(pa.allocated_amount) total_applied'.$j.' JOIN students s ON s.student_id=p.student_id '.$w.' AND p.verified_at>=? AND p.verified_at<? GROUP BY p.payment_id,p.verified_at,p.receipt_number,p.reference_number,p.transaction_type,p.payment_channel ORDER BY p.verified_at DESC',$p);return ['ok'=>true,'timezone'=>AccountingReportingPeriod::TIMEZONE,'scope'=>['academic_year'=>$f['academic_year'],'semester'=>$f['semester'],'period'=>$r['period'],'start_at'=>AccountingReportingPeriod::sql($r['start_at']),'end_exclusive'=>AccountingReportingPeriod::sql($r['end_exclusive']),'payment_channel'=>$f['payment_channel'],'fee_category'=>$f['fee_category']],'section_status'=>['kpis'=>'ok','fee_categories'=>$categories?'ok':'no_data','payment_channels'=>$channels?'ok':'no_data','recent_collections'=>$recent?'ok':'no_data'],'kpis'=>['net_assessed_amount'=>$net,'outstanding_balance'=>$out,'official_academic_collections'=>$current,'term_to_date_collections'=>$cutoff,'collection_efficiency'=>$eff,'efficiency_note'=>'PROVISIONAL ? CLIENT VALIDATION REQUIRED','snapshot_note'=>'Net Assessed Amount and Outstanding Balance are AY/Semester snapshots; category filters apply only to collections.'],'fee_categories'=>$categories,'payment_channels'=>$channels,'recent_collections'=>$recent,'trend'=>['labels'=>[],'current'=>[],'prior'=>[],'comparison_label'=>$r['comparison_label']],'needs_attention'=>[],'integrity_warnings'=>$eff!==null&&$eff>100?['Collection Efficiency exceeds 100%.']:[]];}private function termCutoff($f,$end):float{$p=[];[$j,$w]=$this->base($f,$p);$p[]=AccountingReportingPeriod::sql($end);return $this->num('SELECT COALESCE(SUM(pa.allocated_amount),0)'.$j.$w.' AND p.verified_at<?',$p);}}
